<?php
require_once __DIR__.'/../app/layout.php';$q=trim($_GET['q']??'');$type=trim($_GET['type']??'');$loc=trim($_GET['location']??'');$sql="SELECT j.*,COALESCE(cp.company_name,u.name) company FROM jobs j JOIN users u ON u.id=j.company_id LEFT JOIN company_profiles cp ON cp.user_id=u.id WHERE j.status='Aktif'";$p=[];if($q!==''){$sql.=" AND (j.title LIKE ? OR j.description LIKE ? OR j.skills LIKE ? OR cp.company_name LIKE ?)";$v="%$q%";array_push($p,$v,$v,$v,$v);}if(in_array($type,['Remote','Hybrid','Onsite'],true)){$sql.=' AND j.work_type=?';$p[]=$type;}if($loc!==''){$sql.=' AND j.location LIKE ?';$p[]="%$loc%";}$sql.=' ORDER BY j.created_at DESC';$st=db()->prepare($sql);$st->execute($p);$jobs=$st->fetchAll();page_header('Cari lowongan','jobs'); ?>
<section class="page-hero"><div class="container"><span class="eyebrow">TEMUKAN KESEMPATAN</span><h1>Lowongan yang membuka peluang.</h1><p>Temukan pekerjaan sesuai keterampilan, preferensi kerja, dan kebutuhan aksesibilitasmu.</p></div></section><section class="section"><div class="container jobs-layout"><aside class="panel"><h2>Filter pekerjaan</h2><form method="get" class="form"><label>Kata kunci<input name="q" placeholder="Web developer, desain..." value="<?=e($q)?>"></label><label>Lokasi<input name="location" placeholder="Kota atau remote" value="<?=e($loc)?>"></label><label>Tipe kerja<select name="type"><option value="">Semua tipe</option><?php foreach(['Remote','Hybrid','Onsite'] as $t):?><option <?=$type===$t?'selected':''?>><?=$t?></option><?php endforeach;?></select></label><button class="btn btn-primary full">Terapkan filter</button><a class="btn btn-outline full" href="<?=e(url('jobs.php'))?>">Reset</a></form><p class="tiny">Periksa setiap lowongan untuk mengetahui akomodasi yang tersedia.</p></aside><div><h2>Lowongan tersedia <span class="count">(<?=count($jobs)?>)</span></h2><?php if(!$jobs):?><div class="empty"><h3>Belum ada hasil yang cocok</h3><p>Coba kata kunci atau filter lain.</p></div><?php endif;?><?php foreach($jobs as $j):?><article class="job"><div class="company-logo"><?=e(initials($j['company']))?></div><div class="job-content"><small class="company-name"><?=e($j['company'])?></small><h3><a href="<?=e(url('job.php?id='.(int)$j['id']))?>"><?=e($j['title'])?></a></h3><div class="meta"><span><?=e($j['location']?:'Lokasi fleksibel')?></span><span><?=e($j['work_type'])?></span><span><?=e($j['employment_type'])?></span></div><p><?=e(mb_strimwidth(strip_tags($j['description']),0,150,'…'))?></p><div class="tags"><?php foreach(array_slice(array_filter(array_map('trim',explode(',',$j['accessibility']??''))),0,3) as $tag):?><span class="tag green"><?=e($tag)?></span><?php endforeach;?></div></div><a class="job-arrow" href="<?=e(url('job.php?id='.(int)$j['id']))?>" aria-label="Lihat lowongan">↗</a></article><?php endforeach;?></div></div></section>
<?php page_footer(); ?>
